export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a);
export const smoothstep = (a, b, v) => {
  const t = clamp(invLerp(a, b, v), 0, 1);
  return t * t * (3 - 2 * t);
};
export const mod = (n, m) => ((n % m) + m) % m;

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const pad2 = (n) => String(Math.floor(n)).padStart(2, '0');

/** Seconds since the start of the run -> 09:02:00 style clock. */
export function clockText(seconds, baseHour = 9, baseMinute = 2) {
  const total = Math.max(0, Math.floor(seconds)) + baseMinute * 60 + baseHour * 3600;
  const h = Math.floor(total / 3600) % 24;
  const m = Math.floor(total / 60) % 60;
  const s = total % 60;
  return `${pad2(h)}:${pad2(m)}:${pad2(s)}`;
}

export function deltaText(seconds) {
  const sec = Math.round(seconds);
  if (sec === 0) return '0:00';
  const sign = sec > 0 ? '+' : '−';
  const abs = Math.abs(sec);
  return `${sign}${Math.floor(abs / 60)}:${pad2(abs % 60)}`;
}

export function durationText(seconds) {
  const sec = Math.max(0, Math.round(seconds));
  return `${Math.floor(sec / 60)}:${pad2(sec % 60)}`;
}

export const kmhToMs = (v) => v / 3.6;
export const msToKmh = (v) => v * 3.6;

export function easeOutCubic(t) {
  return 1 - Math.pow(1 - t, 3);
}

/** Interpolate two hex colours. */
export function mixHex(a, b, t) {
  const pa = parseInt(a.slice(1), 16);
  const pb = parseInt(b.slice(1), 16);
  const r = Math.round(lerp((pa >> 16) & 255, (pb >> 16) & 255, t));
  const g = Math.round(lerp((pa >> 8) & 255, (pb >> 8) & 255, t));
  const bl = Math.round(lerp(pa & 255, pb & 255, t));
  return `rgb(${r},${g},${bl})`;
}

export function rgba(hex, alpha) {
  const p = parseInt(hex.slice(1), 16);
  return `rgba(${(p >> 16) & 255},${(p >> 8) & 255},${p & 255},${alpha})`;
}

import { clamp, smoothstep, lerp, mulberry32 } from './util.js';

// ---------------------------------------------------------------------------
// The line: Zürich HB -> Lenzburg -> Olten -> Bern.  Distances are compressed
// for playability (roughly 1:4) but every curve, station and landmark is placed
// to make the cab view feel like the real Midland line.
// ---------------------------------------------------------------------------

export const DS = 2;
export const ROUTE_LENGTH = 21200;

export const STATIONS = [
  {
    id: 'zurich', name: 'Zürich HB', city: 'Zürich', stopS: 200,
    arr: 0, dep: 30, platformSide: 1, platformStart: 0, platformEnd: 310,
    terminal: true, code: 'ZRH',
  },
  {
    id: 'lenzburg', name: 'Lenzburg', city: 'Lenzburg', stopS: 7000,
    arr: 210, dep: 240, platformSide: 1, platformStart: 6770, platformEnd: 7100,
    code: 'LBG',
  },
  {
    id: 'olten', name: 'Olten', city: 'Olten', stopS: 12600,
    arr: 410, dep: 440, platformSide: 1, platformStart: 12370, platformEnd: 12700,
    code: 'OL',
  },
  {
    id: 'bern', name: 'Bern', city: 'Bern', stopS: 20600,
    arr: 660, dep: null, platformSide: 1, platformStart: 20370, platformEnd: 20700,
    terminal: true, code: 'BN',
  },
];

export const TUNNEL = { start: 15300, end: 16700, name: 'Heitersberg' };

export const SIGNALS = [
  920, 2320, 3720, 5120, 6610, 7840, 9110, 10580, 11990, 13520,
  14650, 15860, 17220, 18420, 19820,
].map((s, i) => ({ id: i + 1, s, state: 'green' }));

// The one signal which protects a crossing freight path.
SIGNALS[10].state = 'red';
SIGNALS[9].state = 'amber';
export const RED_SIGNAL_INDEX = 10;

const SPEED_LIMITS = [
  { s: 0, v: 40 },
  { s: 260, v: 60 },
  { s: 620, v: 100 },
  { s: 1250, v: 140 },
  { s: 2050, v: 200 },
  { s: 6000, v: 160 },
  { s: 6450, v: 120 },
  { s: 6730, v: 80 },
  { s: 7260, v: 80 },
  { s: 7520, v: 120 },
  { s: 8120, v: 160 },
  { s: 9020, v: 180 },
  { s: 11180, v: 160 },
  { s: 11920, v: 120 },
  { s: 12340, v: 80 },
  { s: 12600, v: 60 },
  { s: 12920, v: 100 },
  { s: 13380, v: 140 },
  { s: 14120, v: 180 },
  { s: 14780, v: 200 },
  { s: 15200, v: 160 },
  { s: 15320, v: 140 },
  { s: 16700, v: 160 },
  { s: 17280, v: 200 },
  { s: 18900, v: 160 },
  { s: 19580, v: 120 },
  { s: 20080, v: 100 },
  { s: 20380, v: 80 },
  { s: 20600, v: 40 },
  { s: 21200, v: 0 },
];

const CURVES = [
  [620, 1580, 1 / 2200],
  [1660, 2480, -1 / 2700],
  [2540, 3380, 1 / 2600],
  [3460, 4240, -1 / 3000],
  [5000, 5880, -1 / 2300],
  [7600, 8520, 1 / 1900],
  [8600, 9560, -1 / 2300],
  [9640, 10560, 1 / 2500],
  [10660, 11640, -1 / 2800],
  [13180, 14020, 1 / 2100],
  [14120, 14920, -1 / 2500],
  [16900, 17760, 1 / 1850],
  [17860, 18700, -1 / 2200],
  [18800, 19520, 1 / 2700],
];

function regionAt(s) {
  if (s < 2600) return 'zurich';
  if (s < 6700) return 'country';
  if (s < 7320) return 'lenzburg';
  if (s < 11500) return 'country';
  if (s < 12920) return 'olten';
  if (s < TUNNEL.start) return 'country';
  if (s < TUNNEL.end) return 'tunnel';
  if (s < 19600) return 'aare';
  return 'bern';
}
export { regionAt };

function elevationAt(s) {
  return (
    12 * Math.sin(s / 3400 + 0.4) +
    5.5 * Math.sin(s / 980 + 1.2) +
    1.6 * Math.sin(s / 240 + 0.2) +
    (s / ROUTE_LENGTH) * 16
  );
}

function buildRoute() {
  const count = Math.floor(ROUTE_LENGTH / DS) + 1;
  const curvature = new Float32Array(count);
  for (const [a, b, k] of CURVES) {
    const i0 = Math.max(0, Math.floor((a - 220) / DS));
    const i1 = Math.min(count - 1, Math.ceil((b + 220) / DS));
    for (let i = i0; i <= i1; i++) {
      const s = i * DS;
      const ramp = smoothstep(a - 220, a + 30, s) * (1 - smoothstep(b - 30, b + 220, s));
      curvature[i] += k * ramp;
    }
  }
  // Keep station approaches straight and calm.
  for (const st of STATIONS) {
    for (let i = 0; i < count; i++) {
      const s = i * DS;
      const d = Math.abs(s - (st.stopS - 90));
      if (d < 720) curvature[i] *= smoothstep(330, 720, d);
    }
  }

  const route = new Array(count);
  let x = 0;
  let z = 0;
  let heading = 0;
  for (let i = 0; i < count; i++) {
    const s = i * DS;
    route[i] = { s, x, z, elev: elevationAt(s), heading, k: curvature[i] };
    heading += curvature[i] * DS;
    x += Math.sin(heading) * DS;
    z += Math.cos(heading) * DS;
  }
  return route;
}

export const route = buildRoute();

export function sampleRoute(s) {
  const f = clamp(s / DS, 0, route.length - 1);
  const i = Math.floor(f);
  const t = f - i;
  const a = route[i];
  const b = route[Math.min(route.length - 1, i + 1)];
  return {
    s,
    x: lerp(a.x, b.x, t),
    z: lerp(a.z, b.z, t),
    elev: lerp(a.elev, b.elev, t),
    heading: lerp(a.heading, b.heading, t),
    k: lerp(a.k, b.k, t),
  };
}

export function limitAt(s) {
  let v = SPEED_LIMITS[0].v;
  for (const entry of SPEED_LIMITS) {
    if (s >= entry.s) v = entry.v;
    else break;
  }
  return v;
}

export function nextLimitChange(s) {
  for (const entry of SPEED_LIMITS) {
    if (entry.s > s + 4) return { s: entry.s, v: entry.v, distance: entry.s - s };
  }
  return null;
}

export function currentLimitSegment(s) {
  let current = SPEED_LIMITS[0];
  for (const entry of SPEED_LIMITS) {
    if (s >= entry.s) current = entry;
    else break;
  }
  return current;
}

export function stationByS(s) {
  let best = null;
  for (const st of STATIONS) {
    if (s <= st.stopS + 150 && (!best || Math.abs(s - st.stopS) < Math.abs(s - best.stopS))) best = st;
  }
  return best;
}

// ---------------------------------------------------------------------------
// Scenery is generated once, deterministically, so the same pretty farm is
// always in the same meadow.
// ---------------------------------------------------------------------------

const rand = mulberry32(0x51a55e);
const scenery = [];
const fields = [];
const rivers = [];

function add(type, s, lat, opts = {}) {
  scenery.push({
    type, s, lat,
    w: opts.w || 10,
    d: opts.d || 10,
    h: opts.h || 8,
    v: opts.v || 0,
    size: opts.size || 1,
    seed: rand(),
  });
}

function stationZone(s, margin = 30) {
  for (const st of STATIONS) {
    if (s > st.platformStart - margin && s < st.platformEnd + margin) return true;
  }
  return false;
}

function generateScenery() {
  for (let s = 80; s < ROUTE_LENGTH - 80; s += 15) {
    const region = regionAt(s);
    if (region === 'tunnel') continue;
    const inStation = stationZone(s);

    for (const side of [-1, 1]) {
      const r = rand();
      const latBase = 9 + rand() * 34;
      const lat = side * latBase;

      if (inStation) {
        // Keep the platform envelope clear; city details are added by the renderer.
        continue;
      }

      if (region === 'zurich') {
        if (r < 0.055) {
          add('cityblock', s, side * (24 + rand() * 38), {
            w: 16 + rand() * 18, d: 12 + rand() * 16, h: 14 + rand() * 26, v: Math.floor(rand() * 4),
          });
        } else if (r < 0.09) {
          add('tree', s, side * (11 + rand() * 24), { h: 7 + rand() * 7, size: 0.8 + rand() * 0.5 });
        } else if (r < 0.11) {
          add('lamp', s, side * 7.4, { h: 7 });
        } else if (r < 0.125) {
          add('flag', s, side * (16 + rand() * 16), { h: 10 });
        }
      } else if (region === 'country' || region === 'lenzburg') {
        if (r < 0.34) {
          add(rand() < 0.55 ? 'pine' : 'tree', s, side * (10 + rand() * 32), {
            h: 8 + rand() * 11, size: 0.75 + rand() * 0.7,
          });
        } else if (r < 0.395) {
          add('house', s, side * (24 + rand() * 38), {
            w: 10 + rand() * 8, d: 8 + rand() * 7, h: 5 + rand() * 3, v: Math.floor(rand() * 4),
          });
        } else if (r < 0.415) {
          add('barn', s, side * (26 + rand() * 40), {
            w: 13 + rand() * 9, d: 9 + rand() * 5, h: 6 + rand() * 2, v: Math.floor(rand() * 2),
          });
        } else if (r < 0.44) {
          add('cow', s, side * (14 + rand() * 30), { size: 0.8 + rand() * 0.4 });
        } else if (r < 0.465) {
          add('haybale', s, side * (12 + rand() * 28), { size: 0.8 + rand() * 0.4 });
        } else if (r < 0.485) {
          add('fence', s, side * 6.6, { w: 18 + rand() * 14 });
        } else if (r < 0.495) {
          add('flag', s, side * (16 + rand() * 20), { h: 9 });
        }
      } else if (region === 'aare') {
        if (r < 0.48) {
          add(rand() < 0.66 ? 'pine' : 'tree', s, side * (9 + rand() * 44), {
            h: 9 + rand() * 14, size: 0.8 + rand() * 0.8,
          });
        } else if (r < 0.505) {
          add('house', s, side * (28 + rand() * 42), {
            w: 11 + rand() * 8, d: 9 + rand() * 6, h: 5.5 + rand() * 3, v: Math.floor(rand() * 4),
          });
        } else if (r < 0.52) {
          add('castle', s, side * (68 + rand() * 30), { w: 22, d: 16, h: 15, size: 1.2 });
        } else if (r < 0.54) {
          add('cow', s, side * (15 + rand() * 22), { size: 0.8 + rand() * 0.3 });
        }
      } else if (region === 'bern') {
        if (r < 0.075) {
          add('cityblock', s, side * (22 + rand() * 34), {
            w: 14 + rand() * 16, d: 11 + rand() * 12, h: 13 + rand() * 16, v: Math.floor(rand() * 5), oldtown: true,
          });
        } else if (r < 0.12) {
          add('tree', s, side * (10 + rand() * 18), { h: 7 + rand() * 6, size: 0.8 + rand() * 0.4 });
        } else if (r < 0.14) {
          add('flag', s, side * (14 + rand() * 14), { h: 10 });
        }
      }
    }
  }

  // Signature landmarks you can look out for.
  add('church', 4380, 49, { w: 9, d: 18, h: 12, size: 1.1 });
  add('farm', 3680, -38, { w: 18, d: 12, h: 7, v: 1 });
  add('windmill', 9820, -92, { h: 22 });
  add('castle', 17120, -74, { w: 26, d: 18, h: 17, size: 1.3 });
  add('church', 18880, 57, { w: 10, d: 19, h: 13, size: 1.15 });
  add('tower', 20190, 30, { w: 9, d: 9, h: 25, v: 1 });
  add('cityblock', 20260, 44, { w: 26, d: 18, h: 18, v: 2, oldtown: true });
  add('cityblock', 20420, 47, { w: 22, d: 16, h: 15, v: 3, oldtown: true });
  add('cityblock', 19960, -42, { w: 24, d: 16, h: 17, v: 1, oldtown: true });
  add('tree', 20520, -18, { h: 12, size: 1.1 });

  scenery.sort((a, b) => a.s - b.s);
}

function generateFields() {
  const palette = ['#88a85e', '#9ab866', '#b5c27a', '#7a9e58', '#c7bb78', '#a4b66c', '#6f9552'];
  for (const side of [-1, 1]) {
    let s = 200;
    let flip = side === -1;
    while (s < ROUTE_LENGTH - 300) {
      const region = regionAt(s);
      if (region === 'tunnel') { s += 300; continue; }
      if (region === 'zurich' || region === 'bern' || region === 'olten' || region === 'lenzburg') {
        s += 500;
        continue;
      }
      const length = 330 + rand() * 430;
      const l0 = 8 + rand() * 14;
      const l1 = 70 + rand() * 140;
      const color = region === 'aare'
        ? (rand() < 0.5 ? '#5e8451' : '#6f9358')
        : palette[Math.floor(rand() * palette.length)];
      fields.push({ s0: s, s1: s + length, l0, l1, side, color, kind: region, flip });
      flip = !flip;
      // A second, deeper patch gives the landscape layers of colour.
      if (rand() < 0.55) {
        fields.push({
          s0: s + 80 + rand() * 140, s1: s + length + rand() * 120,
          l0: l1 + 18, l1: l1 + 90 + rand() * 90,
          side, color: palette[Math.floor(rand() * palette.length)], kind: region, flip,
        });
      }
      s += length + 90 + rand() * 180;
    }
  }

  // The Aare accompanies the last part of the run.
  rivers.push({ s0: 18160, s1: 19560, side: -1, l0: 17, l1: 95 });
  rivers.push({ s0: 18320, s1: 19480, side: 1, l0: 105, l1: 205, lake: true });
}

generateScenery();
generateFields();

export const scene = { scenery, fields, rivers };
export { scenery, fields, rivers };

