} from './drawlib.js';

// ---------------------------------------------------------------------------
// Scenery art. Everything is drawn from a cab-height camera, so objects are
// billboarded or built from a handful of projected faces. No bitmaps.
// ---------------------------------------------------------------------------

const TAU = Math.PI * 2;

const PALETTE = {
  houseWalls: ['#DED4BE', '#E9E1CE', '#CBBFA8', '#D8C6AC'],
  houseRoofs: ['#7A4E3A', '#5C4034', '#8A5A3C', '#4C413D'],
  cityWalls: ['#C9C6BA', '#B7B5AA', '#D4CFC2', '#A9ABA4'],
  oldWalls: ['#C8AE84', '#D5BE95', '#BCA37C', '#CBB891'],
  oldRoofs: ['#6E4A3A', '#5A3F34', '#7D5642', '#514039'],
};

function shadeTree(ctx, h, alpha, type, seed) {
  const trunkW = Math.max(0.16, h * 0.045);
  ctx.fillStyle = rgba('#67452c', alpha);
  ctx.fillRect(-trunkW / 2, -h * 0.45, trunkW, h * 0.45);

  if (type === 'pine') {
    const levels = 3;
    for (let i = 0; i < levels; i++) {
      const y = -h * (0.34 + i * 0.2);
      const w = h * (0.44 - i * 0.1);
      const top = y - h * 0.34;
      ctx.beginPath();
      ctx.moveTo(0, top);
      ctx.lineTo(w, y);
      ctx.lineTo(-w, y);
      ctx.closePath();
      ctx.fillStyle = i === 0 ? rgba('#2f5b3b', alpha) : rgba(i === 1 ? '#386b44' : '#417a4b', alpha);
      ctx.fill();
    }
    ctx.beginPath();
    ctx.moveTo(-h * 0.06, -h * 0.96);
    ctx.lineTo(-h * 0.34, -h * 0.48);
    ctx.lineTo(h * 0.02, -h * 0.55);
    ctx.closePath();
    ctx.fillStyle = rgba('#5f8f58', alpha * 0.25);
    ctx.fill();
  } else {
    const crownY = -h * 0.68;
    const r = h * 0.31;
    const colors = ['#416e38', '#4e7f40', '#5c8f49'];
    for (let i = 0; i < 3; i++) {
      const a = i * 2.2 + seed * 4;
      const ox = Math.cos(a) * r * 0.38;
      const oy = Math.sin(a) * r * 0.3;
      ctx.beginPath();
      ctx.arc(ox, crownY + oy, r * (1 - i * 0.08), 0, TAU);
      ctx.fillStyle = rgba(colors[i], alpha);
      ctx.fill();
    }
    ctx.beginPath();
    ctx.arc(-r * 0.3, crownY - r * 0.25, r * 0.42, 0, TAU);
    ctx.fillStyle = rgba('#7aa35e', alpha * 0.55);
    ctx.fill();
  }
}

function drawTree(r, obj, p, alpha, t) {
  const h = obj.h * obj.size;
  if (p.k * h < 1.5) return;
  ctx(r);
  const c = r.ctx;
  c.save();
  c.globalAlpha = alpha;
  c.translate(p.x, p.y);
  c.scale(p.k, p.k);
  // ground shadow
  c.beginPath();
  c.ellipse(0.2, 0, h * 0.34, h * 0.075, 0, 0, TAU);
  c.fillStyle = 'rgba(39,58,35,0.18)';
  c.fill();
  shadeTree(c, h, 1, obj.type, obj.seed);
  c.restore();
}

const ctx = (r) => r.ctx;

function drawCow(r, obj, p, alpha) {
  if (p.k < 0.55) return;
  const c = r.ctx;
  c.save();
  c.globalAlpha = alpha;
  c.translate(p.x, p.y);
  c.scale(p.k, p.k);
  const s = obj.size;
  c.fillStyle = '#f1ead9';
  c.beginPath();
  c.ellipse(0, -0.85 * s, 0.72 * s, 0.44 * s, 0, 0, TAU);
  c.fill();
  c.fillStyle = '#7a4c30';
  c.beginPath();
  c.ellipse(-0.18 * s, -0.92 * s, 0.32 * s, 0.24 * s, 0.4, 0, TAU);
  c.fill();
  c.beginPath();
  c.ellipse(0.36 * s, -0.78 * s, 0.22 * s, 0.14 * s, -0.2, 0, TAU);
  c.fill();
  c.fillStyle = '#2f2a26';
  c.fillRect(-0.5 * s, -0.58 * s, 0.13 * s, 0.58 * s);
  c.fillRect(0.4 * s, -0.58 * s, 0.13 * s, 0.58 * s);
  c.beginPath();
  c.arc(0.68 * s, -1.02 * s, 0.23 * s, 0, TAU);
  c.fillStyle = '#f1ead9';
  c.fill();
  c.fillStyle = '#2f2a26';
  c.beginPath();
  c.arc(0.76 * s, -1.06 * s, 0.045 * s, 0, TAU);
  c.fill();
  c.restore();
}

function drawHaybale(r, obj, p, alpha) {
  if (p.k < 0.5) return;
  const c = r.ctx;
  c.save();
  c.globalAlpha = alpha;
  c.translate(p.x, p.y);
  c.scale(p.k, p.k);
  const s = obj.size;
  c.fillStyle = '#b99a58';
  c.beginPath();
  c.ellipse(0, -0.55 * s, 0.7 * s, 0.55 * s, 0, 0, TAU);
  c.fill();
  c.strokeStyle = '#8f743f';
  c.lineWidth = 0.06;
  for (let i = -2; i <= 2; i++) {
    c.beginPath();
    c.ellipse(0, -0.55 * s, 0.7 * s, 0.55 * s, 0, i * 0.4, i * 0.4 + 0.3);
    c.stroke();
  }
  c.restore();
}

function drawFence(r, obj, p, alpha) {
  if (p.k < 0.4) return;
  const c = r.ctx;
  const n = Math.max(2, Math.round(obj.w / 2.6));
  const s0 = obj.s - obj.w / 2;
  const posts = [];
  for (let i = 0; i <= n; i++) {
    const q = r.project(s0 + (obj.w * i) / n, obj.lat, 1.15);
    const b = r.project(s0 + (obj.w * i) / n, obj.lat, 0);
    if (q && b) posts.push({ q, b });
  }
  if (posts.length < 2) return;
  c.save();
  c.globalAlpha = alpha * 0.9;
  c.strokeStyle = '#6d5a44';
  c.lineWidth = Math.max(0.6, p.k * 0.055);
  for (const post of posts) {
    c.beginPath();
    c.moveTo(post.b.x, post.b.y);
    c.lineTo(post.q.x, post.q.y);
    c.stroke();
  }
  c.strokeStyle = '#8a7358';
  c.lineWidth = Math.max(0.5, p.k * 0.045);
  for (const level of [0.45, 0.9]) {
    c.beginPath();
    posts.forEach((post, i) => {
      const y = post.b.y + (post.q.y - post.b.y) * level;
      if (i === 0) c.moveTo(post.b.x, y);
      else c.lineTo(post.b.x, y);
    });
    c.stroke();
  }
  c.restore();
}

function drawFlag(r, obj, p, alpha, t) {
  if (p.k < 0.45) return;
  const h = obj.h;
  const c = r.ctx;
  c.save();
  c.globalAlpha = alpha;
  c.translate(p.x, p.y);
  c.scale(p.k, p.k);
  c.strokeStyle = '#8b8e88';
  c.lineWidth = 0.07;
  c.beginPath();
  c.moveTo(0, 0);
  c.lineTo(0, -h);
  c.stroke();
  const wave = Math.sin(t * 2.3 + obj.seed * 8) * 0.12;
  c.beginPath();
  c.moveTo(0, -h);
  c.quadraticCurveTo(1.1, -h + 0.15 + wave, 2.2, -h + 0.05);
  c.lineTo(2.2, -h + 1.15);
  c.quadraticCurveTo(1.1, -h + 1.25 - wave, 0, -h + 1.25);
  c.closePath();
  c.fillStyle = '#d92b2b';
  c.fill();
  c.fillStyle = '#fff';
  c.fillRect(0.95, -h + 0.5, 0.3, 0.9);
  c.fillRect(0.65, -h + 0.8, 0.9, 0.3);
  c.restore();
}

function drawLamp(r, obj, p, alpha) {
  if (p.k < 0.5) return;
  const c = r.ctx;
  c.save();
  c.globalAlpha = alpha;
  c.translate(p.x, p.y);
  c.scale(p.k, p.k);
  c.strokeStyle = '#4f5450';
  c.lineWidth = 0.09;
  c.beginPath();
  c.moveTo(0, 0);
  c.lineTo(0, -obj.h);
  c.quadraticCurveTo(0.1, -obj.h - 0.4, 0.75, -obj.h - 0.4);
  c.stroke();
  c.fillStyle = '#e8d9a7';
  c.beginPath();
  c.ellipse(0.78, -obj.h - 0.33, 0.22, 0.1, 0, 0, TAU);
  c.fill();
  c.restore();
}

function drawWindmill(r, obj, p, alpha, t) {
  if (p.k < 0.3) return;
  const c = r.ctx;
  c.save();
  c.globalAlpha = alpha;
  c.translate(p.x, p.y);
  c.scale(p.k, p.k);
  c.fillStyle = '#d6d3c8';
  c.beginPath();
  c.moveTo(-1.6, 0);
  c.lineTo(-0.9, -obj.h);
  c.lineTo(0.9, -obj.h);
  c.lineTo(1.6, 0);
  c.closePath();
  c.fill();
  c.fillStyle = '#8f918a';
  c.beginPath();
  c.moveTo(-1.1, 0);
  c.lineTo(-0.7, -obj.h * 0.92);
  c.lineTo(0.6, -obj.h * 0.92);
  c.lineTo(1.0, 0);
  c.closePath();
  c.fill();
  c.save();
  c.translate(0, -obj.h);
  c.rotate(t * 0.55 + obj.seed);
  c.strokeStyle = '#e8e4d9';
  c.lineWidth = 0.28;
  for (let i = 0; i < 3; i++) {
    c.rotate(TAU / 3);
    c.beginPath();
    c.moveTo(0, 0);
    c.lineTo(0, -10.5);
    c.stroke();
  }
  c.fillStyle = '#eeeae0';
  c.beginPath();
  c.arc(0, 0, 0.65, 0, TAU);
  c.fill();
  c.restore();
  c.restore();
}

// ---------------------------------------------------------------------------
// Buildings
// ---------------------------------------------------------------------------

function wallsFor(obj) {
  if (obj.type === 'cityblock') {
    return {
      wall: PALETTE.cityWalls[obj.v % PALETTE.cityWalls.length],
      roof: PALETTE.houseRoofs[obj.v % PALETTE.houseRoofs.length],
      flat: true,
    };
  }
  if (obj.oldtown) {
    return {
      wall: PALETTE.oldWalls[obj.v % PALETTE.oldWalls.length],
      roof: PALETTE.oldRoofs[obj.v % PALETTE.oldRoofs.length],
      flat: false,
    };
  }
  return {
    wall: PALETTE.houseWalls[obj.v % PALETTE.houseWalls.length],
    roof: PALETTE.houseRoofs[obj.v % PALETTE.houseRoofs.length],
    flat: false,
  };
}

function drawBuilding(r, obj, p, alpha, opts = {}) {
  const c = r.ctx;
  const wall = opts.wall || wallsFor(obj).wall;
  const roof = opts.roof || wallsFor(obj).roof;
  const flat = opts.flat ?? wallsFor(obj).flat;
  const s0 = obj.s - obj.w / 2;
  const s1 = obj.s + obj.w / 2;
  const l0 = obj.lat - obj.d / 2;
  const l1 = obj.lat + obj.d / 2;
  const sideLat = obj.lat >= 0 ? l0 : l1;
  const h = obj.h;

  const b0 = r.project(s0, sideLat, 0);
  const b1 = r.project(s1, sideLat, 0);
  const t0 = r.project(s0, sideLat, h);
  const t1 = r.project(s1, sideLat, h);
  if (!b0 || !b1 || !t0 || !t1) return;

  const wpx = Math.abs(b1.x - b0.x);
  if (wpx < 1.2) return;

  c.save();
  c.globalAlpha = alpha;

  // track-facing side
  fillQuad(c, b0, b1, t1, t0, shade(wall, 0));
  // subtle vertical shading
  const grad = c.createLinearGradient(b0.x, 0, b1.x, 0);
  grad.addColorStop(0, 'rgba(255,255,255,0.10)');
  grad.addColorStop(0.5, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.10)');
  fillQuad(c, b0, b1, t1, t0, grad);

  // near end
  const n0 = r.project(s0, l0, 0);
  const n1 = r.project(s0, l1, 0);
  const n2 = r.project(s0, l1, h);
  const n3 = r.project(s0, l0, h);
  if (n0 && n1 && n2 && n3 && r.camS < s0) {
    fillQuad(c, n0, n1, n2, n3, shade(wall, -18));
  }

  // foundation
  const f0 = r.project(s0, sideLat, 0.55);
  const f1 = r.project(s1, sideLat, 0.55);
  if (f0 && f1) {
    c.globalAlpha = alpha * 0.65;
    fillQuad(c, b0, b1, f1, f0, shade(wall, -34));
    c.globalAlpha = alpha;
  }

  // windows
  if (wpx > 26) {
    const q = [b0, b1, t1, t0];
    const cols = Math.max(1, Math.min(5, Math.floor(obj.w / 3.6)));
    const rows = Math.max(1, Math.min(4, Math.floor(h / 3.4)));
    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const u0 = (col + 0.28) / cols;
        const u1 = (col + 0.72) / cols;
        const v0 = 0.2 + row * (0.58 / rows);
        const v1 = v0 + 0.26 / rows + 0.08;
        const lit = ((obj.seed * 977 + row * 31 + col * 17) % 11) < 2;
        const qq = [
          quadPoint(q, u0, v0), quadPoint(q, u1, v0),
          quadPoint(q, u1, v1), quadPoint(q, u0, v1),
        ];
        polyFill(c, qq, lit ? '#d8b56f' : 'rgba(57,72,78,0.82)');
        if (!lit) {
          c.globalAlpha = alpha * 0.35;
          polyFill(c, [qq[0], qq[1], lerpPt(qq[1], qq[2], 0.5), lerpPt(qq[0], qq[3], 0.5)], '#9fb4b8');
          c.globalAlpha = alpha;
        }
      }
    }
  }

  // roof
  if (flat) {
    const r0 = r.project(s0, l0, h);
    const r1 = r.project(s1, l0, h);
    const r2 = r.project(s1, l1, h);
    const r3 = r.project(s0, l1, h);
    if (r0 && r1 && r2 && r3) {
      polyFill(c, [r0, r1, r2, r3], shade(roof, 8));
      polyStroke(c, [r0, r1, r2, r3], 'rgba(0,0,0,0.18)', Math.max(0.5, p.k * 0.03));
    }
    // parapet
    const pr = r.project(s1, sideLat, h);
    if (pr) {
      c.strokeStyle = 'rgba(255,255,255,0.16)';
      c.lineWidth = Math.max(0.5, p.k * 0.05);
      c.beginPath();
      c.moveTo(t0.x, t0.y);
      c.lineTo(t1.x, t1.y);
      c.stroke();
    }
  } else {
    const rh = Math.min(4.2, Math.max(1.8, h * 0.36));
    const ridgeLat = obj.lat;
    const e0 = r.project(s0, sideLat, h);
    const e1 = r.project(s1, sideLat, h);
    const g0 = r.project(s0, ridgeLat, h + rh);
    const g1 = r.project(s1, ridgeLat, h + rh);
    if (e0 && e1 && g0 && g1) {
      fillQuad(c, e0, e1, g1, g0, roof);
      c.globalAlpha = alpha * 0.35;
      fillQuad(c, e0, e1, lerpPt(e1, g1, 0.15), lerpPt(e0, g0, 0.15), '#ffffff');
      c.globalAlpha = alpha;
      c.strokeStyle = 'rgba(0,0,0,0.24)';
      c.lineWidth = Math.max(0.5, p.k * 0.04);
      c.beginPath();
      c.moveTo(g0.x, g0.y);
      c.lineTo(g1.x, g1.y);
      c.stroke();
    }
    if (r.camS < s0) {
      const ga = r.project(s0, l0, h);
      const gb = r.project(s0, l1, h);
      const gc = r.project(s0, ridgeLat, h + rh);
      if (ga && gb && gc) {
        polyFill(c, [ga, gb, gc], shade(wall, -8));
        polyStroke(c, [ga, gb, gc], 'rgba(0,0,0,0.15)', Math.max(0.5, p.k * 0.03));
      }
    }
  }

  c.restore();
}

function drawChurch(r, obj, p, alpha) {
  const nave = { ...obj, type: 'house', w: obj.w, d: obj.d, h: obj.h };
  drawBuilding(r, nave, p, alpha, { wall: '#e3dccb', roof: '#6f4d3d' });
  const towerS = obj.s - obj.w / 2 - 1.5;
  const tp = r.project(towerS, obj.lat, 0);
  if (!tp) return;
  const h = obj.h + 10;
  const c = r.ctx;
  c.save();
  c.globalAlpha = alpha;
  c.translate(tp.x, tp.y);
  c.scale(tp.k, tp.k);
  const w = 4.2;
  c.fillStyle = '#e9e2d2';
  c.fillRect(-w / 2, -h, w, h);
  c.fillStyle = '#d3c9b7';
  c.fillRect(0, -h, w / 2, h);
  c.fillStyle = '#5a5148';
  c.fillRect(-w / 2 + 0.8, -h + 2.2, 1.1, 2.2);
  c.fillRect(0.4, -h + 2.2, 1.1, 2.2);
  // clock
  c.beginPath();
  c.arc(0, -h * 0.68, 1.15, 0, TAU);
  c.fillStyle = '#f1ebda';
  c.fill();
  c.strokeStyle = '#3a3833';
  c.lineWidth = 0.15;
  c.stroke();
  c.beginPath();
  c.moveTo(0, -h * 0.68);
  c.lineTo(0, -h * 0.68 - 0.7);
  c.moveTo(0, -h * 0.68);
  c.lineTo(0.55, -h * 0.68 + 0.25);
  c.stroke();
  // spire
  c.beginPath();
  c.moveTo(-w * 0.72, -h);
  c.lineTo(0, -h - 8.5);
  c.lineTo(w * 0.72, -h);
  c.closePath();
  c.fillStyle = '#4f6b5d';
  c.fill();
  c.fillStyle = 'rgba(255,255,255,0.12)';
  c.beginPath();
  c.moveTo(-w * 0.72, -h);
  c.lineTo(0, -h - 8.5);
  c.lineTo(0, -h);
  c.closePath();
  c.fill();
  c.strokeStyle = '#313d37';
  c.lineWidth = 0.12;
  c.beginPath();
  c.moveTo(0, -h - 8.5);
  c.lineTo(0, -h - 9.4);
  c.moveTo(-0.5, -h - 9);
  c.lineTo(0.5, -h - 9);
  c.stroke();
  c.restore();
}

function drawCastle(r, obj, p, alpha) {
  const c = r.ctx;
  // mound
  const base = r.project(obj.s, obj.lat, 0);
  if (base) {
    c.save();
    c.globalAlpha = alpha * 0.8;
    c.fillStyle = '#4e6c43';
    c.beginPath();
    c.ellipse(base.x, base.y, 20 * base.k, 4.2 * base.k, 0, 0, TAU);
    c.fill();
    c.restore();
  }
  drawBuilding(r, { ...obj, type: 'cityblock', oldtown: true, v: 1 }, p, alpha, {
    wall: '#bcae92', roof: '#5f4a3c', flat: false,
  });
  // two towers
  for (const [ds, w] of [[-obj.w * 0.34, 3.8], [obj.w * 0.3, 4.6]]) {
    const tp = r.project(obj.s + ds, obj.lat + obj.d * 0.32, 0);
    if (!tp) continue;
    c.save();
    c.globalAlpha = alpha;
    c.translate(tp.x, tp.y);
    c.scale(tp.k, tp.k);
    const h = obj.h + 7;
    c.fillStyle = '#c3b393';
    c.fillRect(-w / 2, -h, w, h);
    c.fillStyle = '#9e8e73';
    c.fillRect(0, -h, w / 2, h);
    // crenellations
    for (let i = -1; i <= 1; i++) {
      c.fillStyle = '#b4a486';
      c.fillRect(i * w * 0.35 - w * 0.12, -h - 1.1, w * 0.24, 1.1);
    }
    c.fillStyle = '#4f4a40';
    c.fillRect(-w * 0.16, -h + 2.2, w * 0.3, 1.8);
    c.restore();
  }
}

function drawTower(r, obj, p, alpha) {
  if (p.k < 0.4) return;
  const c = r.ctx;
  const h = obj.h;
  const w = obj.w;
  c.save();
  c.globalAlpha = alpha;
  c.translate(p.x, p.y);
  c.scale(p.k, p.k);
  c.fillStyle = '#c7b18b';
  c.fillRect(-w / 2, -h, w, h);
  c.fillStyle = '#ab9673';
  c.fillRect(0, -h, w / 2, h);
  // arched passage
  c.fillStyle = '#3b3731';
  c.beginPath();
  c.moveTo(-1.6, 0);
  c.lineTo(-1.6, -4.2);
  c.quadraticCurveTo(0, -6.2, 1.6, -4.2);
  c.lineTo(1.6, 0);
  c.closePath();
  c.fill();
  // clock
  c.beginPath();
  c.arc(0, -h * 0.64, 2.5, 0, TAU);
  c.fillStyle = '#dfc477';
  c.fill();
  c.strokeStyle = '#4c3f2a';
  c.lineWidth = 0.28;
  c.stroke();
  c.beginPath();
  c.arc(0, -h * 0.64, 1.9, 0, TAU);
  c.strokeStyle = '#8f7441';
  c.lineWidth = 0.12;
  c.stroke();
  c.strokeStyle = '#3c3428';
  c.lineWidth = 0.26;
  c.beginPath();
  c.moveTo(0, -h * 0.64);
  c.lineTo(0, -h * 0.64 - 1.4);
  c.moveTo(0, -h * 0.64);
  c.lineTo(0.9, -h * 0.64 + 0.5);
  c.stroke();
  // roof
  c.beginPath();
  c.moveTo(-w * 0.7, -h);
  c.lineTo(0, -h - 6.5);
  c.lineTo(w * 0.7, -h);
  c.closePath();
  c.fillStyle = '#5d4438';
  c.fill();
  c.fillStyle = 'rgba(255,255,255,0.12)';
  c.beginPath();
  c.moveTo(-w * 0.7, -h);
  c.lineTo(0, -h - 6.5);
  c.lineTo(0, -h);
  c.closePath();
  c.fill();
  c.restore();
}

function drawSceneryObject(r, obj, p, alpha, t) {
  const hpx = obj.h * p.k;
  if (p.x < -hpx * 3 - 80 || p.x > r.W + hpx * 3 + 80) return;
  switch (obj.type) {
    case 'tree':
    case 'pine':
      drawTree(r, obj, p, alpha, t);
      break;
    case 'cow':
      drawCow(r, obj, p, alpha);
      break;
    case 'haybale':
      drawHaybale(r, obj, p, alpha);
      break;
    case 'fence':
      drawFence(r, obj, p, alpha);
      break;
    case 'flag':
      drawFlag(r, obj, p, alpha, t);
      break;
    case 'lamp':
      drawLamp(r, obj, p, alpha);
      break;
    case 'windmill':
      drawWindmill(r, obj, p, alpha, t);
      break;
    case 'house':
    case 'barn':
    case 'farm':
    case 'cityblock':
      drawBuilding(r, obj, p, alpha);
      break;
    case 'church':
      drawChurch(r, obj, p, alpha);
      break;
    case 'castle':
      drawCastle(r, obj, p, alpha);
      break;
    case 'tower':
      drawTower(r, obj, p, alpha);
      break;
  }
}

export {
  drawSceneryObject, drawBuilding, drawTower, drawChurch, drawCastle,
  shadeTree,
};

import { clamp, rgba } from './util.js';
import { fillQuad, polyFill, polyStroke } from './drawlib.js';

export const TRAINS = {
  ic2000: {
    id: 'ic2000',
    name: 'IC 2000',
    formation: 'Re 460 + 7 IC2000',
    short: 'Re 460',
    accent: '#d8232a',
    cab: '#171a1d',
    trim: '#d8232a',
    info: 'Double-decker IC set · 200 km/h',
  },
  twindexx: {
    id: 'twindexx',
    name: 'Twindexx',
    formation: 'RABe 502 · FV-Dosto',
    short: 'RABe 502',
    accent: '#d8232a',
    cab: '#202428',
    trim: '#e5e2da',
    info: 'Double-decker EMU · 200 km/h',
  },
};

/**
 * A parked / passing double-decker train seen from the side. Used at Zürich HB
 * and Bern so the other members of the SBB long-distance family are present.
 */
export function drawTrainSide(r, opts) {
  const { s0, s1, lat, type = 'ic2000', alpha = 1, t = 0 } = opts;
  const c = r.ctx;
  const a = r.project(s0, lat, 0);
  const b = r.project(s1, lat, 0);
  if (!a || !b) return;
  if (Math.abs(b.x - a.x) < 2 && Math.abs(a.y - b.y) < 2) return;

  const step = 12;
  const segments = Math.max(1, Math.ceil((s1 - s0) / step));
  const isTwi = type === 'twindexx';
  c.save();
  c.globalAlpha = alpha;

  for (let i = 0; i < segments; i++) {
    const sa = s0 + ((s1 - s0) * i) / segments;
    const sb = s0 + ((s1 - s0) * (i + 1)) / segments;
    const p0 = r.project(sa, lat, 0);
    const p1 = r.project(sb, lat, 0);
    if (!p0 || !p1) continue;
    if (Math.max(p0.x, p1.x) < -40 || Math.min(p0.x, p1.x) > r.W + 40) continue;

    const y = (h) => r.project(sa, lat, h);
    const yb = (h) => r.project(sb, lat, h);
    const bodyLo = 0.55, bodyHi = 4.25;
    // body
    fillQuad(c, y(bodyLo), yb(bodyLo), yb(bodyHi), y(bodyHi), isTwi ? '#e9e6de' : '#eeeae2');
    // lower red band
    fillQuad(c, y(0.55), yb(0.55), yb(1.05), y(1.05), '#c8232c');
    // window bands (lower + upper decks)
    fillQuad(c, y(1.25), yb(1.25), yb(1.95), y(1.95), 'rgba(38,50,56,0.92)');
    fillQuad(c, y(2.55), yb(2.55), yb(3.25), y(3.25), 'rgba(38,50,56,0.92)');
    // window dividers
    const segK = Math.abs(p1.x - p0.x);
    if (segK > 6) {
      c.strokeStyle = 'rgba(235,232,224,0.35)';
      c.lineWidth = Math.max(0.5, segK * 0.02);
      for (const yy of [1.6, 2.9]) {
        c.beginPath();
        c.moveTo(y(yy).x, y(yy).y);
        c.lineTo(yb(yy).x, yb(yy).y);
        c.stroke();
      }
    }
    // roof
    fillQuad(c, y(4.25), yb(4.25), yb(4.45), y(4.45), '#92958f');
    // doors every ~35 m
    if (((i + (isTwi ? 1 : 2)) % 3) === 0) {
      const dx0 = 0.18, dx1 = 0.82;
      const ds = sb - sa;
      const q0 = r.project(sa + ds * dx0, lat, 0.55);
      const q1 = r.project(sa + ds * dx1, lat, 0.55);
      const q2 = r.project(sa + ds * dx1, lat, 3.7);
      const q3 = r.project(sa + ds * dx0, lat, 3.7);
      if (q0 && q1 && q2 && q3) polyFill(c, [q0, q1, q2, q3], 'rgba(200,35,44,0.9)');
    }
    // bogie / shadow
    const sh0 = r.project(sa, lat, 0.15);
    const sh1 = r.project(sb, lat, 0.15);
    if (sh0 && sh1) {
      c.fillStyle = 'rgba(25,28,30,0.9)';
      c.beginPath();
      c.moveTo(sh0.x, sh0.y);
      c.lineTo(sh1.x, sh1.y);
      c.lineTo(sh1.x, sh1.y + Math.max(1, r.focal / 200));
      c.lineTo(sh0.x, sh0.y + Math.max(1, r.focal / 200));
      c.closePath();
      c.fill();
    }
  }

  // front face at the far end
  if (Math.abs(b.x - a.x) > 4) {
    const f0 = r.project(s1, lat - 1.4, 0.5);
    const f1 = r.project(s1, lat + 1.4, 0.5);
    const f2 = r.project(s1, lat + 1.4, 4.1);
    const f3 = r.project(s1, lat - 1.4, 4.1);
    if (f0 && f1 && f2 && f3) {
      polyFill(c, [f0, f1, f2, f3], isTwi ? '#d8232a' : '#c8232c');
      const w0 = r.project(s1, lat - 1.05, 2.5);
      const w1 = r.project(s1, lat + 1.05, 2.5);
      const w2 = r.project(s1, lat + 1.05, 3.6);
      const w3 = r.project(s1, lat - 1.05, 3.6);
      if (w0 && w1 && w2 && w3) polyFill(c, [w0, w1, w2, w3], '#263136');
    }
  }

  c.restore();
}

