// ---------------------------------------------------------------------------
// Small procedural soundscape. Everything is synthesised: no audio files, no
// network requests. The engine is deliberately quiet until the first gesture.
// ---------------------------------------------------------------------------

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.muted = false;
    this.master = null;
    this.noiseBuffer = null;
    this.nodes = null;
    this.lastDoor = 0;
  }

  async unlock() {
    if (!this.ctx) this.init();
    if (!this.ctx) return;
    if (this.ctx.state === 'suspended') {
      try { await this.ctx.resume(); } catch { /* ignored */ }
    }
    this.ready = this.ctx.state === 'running';
    this.applyMute();
  }

  init() {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
    } catch {
      this.ctx = null;
      return;
    }
    const ctx = this.ctx;
    const master = ctx.createGain();
    master.gain.value = this.muted ? 0 : 0.55;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -22;
    comp.knee.value = 18;
    comp.ratio.value = 4;
    comp.attack.value = 0.01;
    comp.release.value = 0.3;
    master.connect(comp);
    comp.connect(ctx.destination);
    this.master = master;

    const len = Math.floor(ctx.sampleRate * 2);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.72 + white * 0.28;
      data[i] = last;
    }
    this.noiseBuffer = buf;

    const noise = (filterType, freq, q = 0.8) => {
      const src = ctx.createBufferSource();
      src.buffer = buf;
      src.loop = true;
      src.playbackRate.value = 0.8 + Math.random() * 0.1;
      const filter = ctx.createBiquadFilter();
      filter.type = filterType;
      filter.frequency.value = freq;
      filter.Q.value = q;
      const gain = ctx.createGain();
      gain.gain.value = 0;
      src.connect(filter);
      filter.connect(gain);
      gain.connect(master);
      src.start();
      return { src, filter, gain };
    };

    const rolling = noise('bandpass', 520, 0.65);
    const rumble = noise('lowpass', 150, 0.9);
    const brake = noise('highpass', 2550, 0.9);
    const tunnel = noise('lowpass', 340, 0.7);
    tunnel.src.playbackRate.value = 0.45;

    const motorGain = ctx.createGain();
    motorGain.gain.value = 0;
    const motorFilter = ctx.createBiquadFilter();
    motorFilter.type = 'lowpass';
    motorFilter.frequency.value = 320;
    motorFilter.Q.value = 3.5;
    motorGain.connect(motorFilter);
    motorFilter.connect(master);
    const motorA = ctx.createOscillator();
    motorA.type = 'sawtooth';
    motorA.frequency.value = 42;
    const motorB = ctx.createOscillator();
    motorB.type = 'triangle';
    motorB.frequency.value = 84;
    const motorBgain = ctx.createGain();
    motorBgain.gain.value = 0.35;
    motorA.connect(motorGain);
    motorB.connect(motorBgain);
    motorBgain.connect(motorGain);
    motorA.start();
    motorB.start();

    this.nodes = {
      rolling, rumble, brake, tunnel, motorA, motorB, motorGain, motorFilter,
    };
    this.ready = true;
  }

  applyMute() {
    if (!this.master || !this.ctx) return;
    const target = this.muted ? 0 : 0.55;
    this.master.gain.setTargetAtTime(target, this.ctx.currentTime, 0.08);
  }

  toggleMute() {
    this.muted = !this.muted;
    this.applyMute();
    return this.muted;
  }

  setMuted(value) {
    this.muted = !!value;
    this.applyMute();
  }

  update(status, dt = 0.016) {
    if (!this.ready || !this.ctx || !this.nodes) return;
    const t = this.ctx.currentTime;
    const speed = Math.max(0, status.speed ?? 0);
    const ratio = Math.min(1.3, speed / 55);
    const power = Math.max(0, status.power ?? 0);
    const brake = Math.max(0, status.brake ?? 0);
    const tunnel = !!status.tunnel;
    const n = this.nodes;
    const smooth = (param, value, tc = 0.12) => {
      if (Math.abs(param.value - value) > 0.0004) param.setTargetAtTime(value, t, tc);
    };

    smooth(n.rolling.gain.gain, ratio > 0.01 ? 0.055 + ratio * 0.085 : 0, 0.16);
    smooth(n.rolling.filter.frequency, 330 + ratio * 700, 0.2);
    smooth(n.rolling.src.playbackRate, 0.72 + ratio * 0.5, 0.25);

    smooth(n.rumble.gain.gain, tunnel ? 0.14 : 0.02 + ratio * 0.055, tunnel ? 0.22 : 0.18);
    smooth(n.tunnel.gain.gain, tunnel ? 0.13 : 0, 0.3);

    smooth(n.motorGain.gain, power > 0.01 ? 0.019 + power * 0.05 : 0.004, 0.1);
    smooth(n.motorA.frequency, 36 + power * 18 + ratio * 26, 0.16);
    smooth(n.motorB.frequency, 74 + power * 34 + ratio * 48, 0.16);
    smooth(n.motorFilter.frequency, 210 + power * 500 + ratio * 260, 0.2);

    smooth(n.brake.gain.gain, brake * ratio * 0.075, 0.09);
    smooth(n.brake.filter.frequency, 2100 + brake * 1800, 0.15);

    void dt;
  }

  horn() {
    if (!this.ready || !this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const out = ctx.createGain();
    out.gain.setValueAtTime(0, t);
    out.gain.linearRampToValueAtTime(0.16, t + 0.05);
    out.gain.setValueAtTime(0.16, t + 0.62);
    out.gain.exponentialRampToValueAtTime(0.001, t + 1.25);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 1900;
    out.connect(filter);
    filter.connect(this.master);
    for (const f of [311, 370]) {
      const osc = ctx.createOscillator();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(f, t);
      osc.frequency.linearRampToValueAtTime(f * 0.98, t + 1.1);
      const g = ctx.createGain();
      g.gain.value = 0.5;
      osc.connect(g);
      g.connect(out);
      osc.start(t);
      osc.stop(t + 1.28);
    }
  }

  chime(double = true) {
    if (!this.ready || !this.ctx) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime;
    const notes = double ? [880, 1174.7] : [988];
    notes.forEach((f, i) => {
      const t = t0 + i * 0.19;
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = f;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(0.11, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.7);
      osc.connect(g);
      g.connect(this.master);
      osc.start(t);
      osc.stop(t + 0.72);
    });
  }

  door() {
    if (!this.ready || !this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this.lastDoor < 0.4) return;
    this.lastDoor = now;
    this.chime(false);
    // pneumatic hiss
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 1600;
    filter.Q.value = 0.6;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, now);
    g.gain.linearRampToValueAtTime(0.06, now + 0.03);
    g.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(now);
    src.stop(now + 0.52);
  }

  brakeSqueal() {
    if (!this.ready || !this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(2600, t);
    filter.frequency.exponentialRampToValueAtTime(1500, t + 0.9);
    filter.Q.value = 8;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(0.045, t + 0.08);
    g.gain.exponentialRampToValueAtTime(0.001, t + 1.1);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + 1.15);
  }
}

/* --------------------------------------------------------------------------
   IR 16 · Mittelland Driver
   A Swiss railway interface: warm paper, signal red, deep cab charcoal.
   -------------------------------------------------------------------------- */

@font-face {
  font-family: "Instrument Sans";
  src: url("./assets/fonts/InstrumentSans-Variable.woff2") format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Instrument Sans";
  src: url("./assets/fonts/InstrumentSans-Italic.woff2") format("woff2");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: "Instrument Serif";
  src: url("./assets/fonts/InstrumentSerif-Regular.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Instrument Serif";
  src: url("./assets/fonts/InstrumentSerif-Italic.ttf") format("truetype");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: "IBM Plex Mono";
  src: url("./assets/fonts/IBMPlexMono-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "IBM Plex Mono";
  src: url("./assets/fonts/IBMPlexMono-Medium.woff2") format("woff2");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "IBM Plex Mono";
  src: url("./assets/fonts/IBMPlexMono-SemiBold.woff2") format("woff2");
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}

:root {
  --paper: #f4f0e6;
  --paper-dim: #d7d2c5;
  --ink: #101518;
  --ink-2: #1a2226;
  --red: #d8232a;
  --red-deep: #9f151b;
  --blue: #15528c;
  --green: #35b97a;
  --amber: #efae3d;
  --panel: rgba(12, 17, 20, 0.78);
  --panel-line: rgba(244, 240, 230, 0.16);
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.42);
  --sans: "Instrument Sans", "Helvetica Neue", Arial, sans-serif;
  --serif: "Instrument Serif", Georgia, serif;
  --mono: "IBM Plex Mono", "SFMono-Regular", Consolas, monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #0d1214;
  color: var(--paper);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

body {
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}

button:focus-visible {
  outline: 3px solid #f3c34a;
  outline-offset: 3px;
}

.is-hidden { display: none !important; }

.app {
  position: relative;
  width: 100%;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  background: #0d1214;
}

#view {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

/* ------------------------------------------------------------------ HUD --- */

.hud {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: max(14px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right))
    max(16px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
}

.hud button { pointer-events: auto; }

.topbar {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 18px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.sbb-mark {
  display: inline-flex;
  align-items: baseline;
  gap: 2px;
  padding: 5px 8px 4px;
  border-radius: 4px;
  background: var(--red);
  box-shadow: 0 4px 14px rgba(216, 35, 42, 0.35);
  line-height: 1;
  white-space: nowrap;
}
.sbb-mark b {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.06em;
}
.sbb-mark i {
  font-size: 8px;
  font-style: normal;
  font-weight: 700;
  opacity: 0.82;
  letter-spacing: 0.08em;
}

.line-badge {
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  padding: 5px 8px;
  border: 1px solid rgba(244, 240, 230, 0.4);
  border-radius: 4px;
  background: rgba(8, 12, 14, 0.45);
  white-space: nowrap;
}

.brand-route {
  color: rgba(244, 240, 230, 0.8);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.brand-route span { color: var(--red); padding: 0 3px; }

.clock-block {
  text-align: center;
  line-height: 1;
  padding: 8px 18px 9px;
  border-radius: 12px;
  background: rgba(8, 12, 14, 0.58);
  border: 1px solid rgba(244, 240, 230, 0.12);
  backdrop-filter: blur(8px);
}
.clock {
  font-family: var(--mono);
  font-size: 23px;
  font-weight: 500;
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
}
.punctuality {
  margin-top: 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--green);
}
.punctuality.late { color: var(--amber); }
.punctuality.very-late { color: #ff6b5e; }

.top-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.icon-btn {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(244, 240, 230, 0.22);
  background: rgba(8, 12, 14, 0.58);
  backdrop-filter: blur(8px);
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}
.icon-btn:hover { background: rgba(35, 44, 48, 0.9); border-color: rgba(244, 240, 230, 0.4); }
.icon-btn:active { transform: scale(0.94); }
.icon-btn svg { width: 19px; height: 19px; fill: currentColor; }
.icon-btn.is-muted .wave { display: none; }
.icon-btn.is-muted { color: rgba(244, 240, 230, 0.45); }

/* route strip ------------------------------------------------------------- */

.route-strip {
  pointer-events: none;
  margin: 12px 4px 0;
  padding: 12px 18px 9px;
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(8, 12, 14, 0.7), rgba(8, 12, 14, 0.38));
  border: 1px solid rgba(244, 240, 230, 0.1);
  backdrop-filter: blur(10px);
}

.route-track {
  position: relative;
  height: 3px;
  border-radius: 3px;
  background: rgba(244, 240, 230, 0.2);
}
.route-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 0;
  border-radius: 3px;
  background: linear-gradient(90deg, #f0c44d, var(--red));
  box-shadow: 0 0 12px rgba(216, 35, 42, 0.5);
}
.route-train {
  position: absolute;
  top: 50%;
  left: 0;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: var(--paper);
  border: 2px solid var(--red);
  box-shadow: 0 0 0 3px rgba(216, 35, 42, 0.24);
}

.stops {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  margin-top: 9px;
}
.stop {
  position: relative;
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.55);
  white-space: nowrap;
}
.stop::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -14px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  transform: translateX(-50%);
  background: rgba(244, 240, 230, 0.35);
}
.stop.done { color: var(--paper); }
.stop.done::before { background: var(--red); }
.stop.current { color: #ffe7a3; }
.stop.current::before {
  background: var(--paper);
  box-shadow: 0 0 0 3px rgba(255, 231, 163, 0.25);
}

/* bottom ------------------------------------------------------------------ */

.hud-bottom {
  display: grid;
  grid-template-columns: minmax(210px, 300px) minmax(280px, auto) minmax(210px, 290px);
  align-items: end;
  justify-content: space-between;
  gap: 16px;
}

.panel {
  pointer-events: auto;
  border-radius: 18px;
  border: 1px solid var(--panel-line);
  background: var(--panel);
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px) saturate(115%);
}

/* speed panel */

.speed-panel {
  padding: 15px 18px 13px;
}
.speed-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.speed-value {
  font-family: var(--mono);
  font-size: 58px;
  font-weight: 500;
  line-height: 0.9;
  letter-spacing: -0.06em;
  font-variant-numeric: tabular-nums;
}
.unit {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.55);
}
.limit-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 9px;
}
.limit-sign {
  width: 35px;
  height: 35px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #f7f3e7;
  border: 5px solid var(--red);
  color: #191b1c;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  flex: 0 0 auto;
}
.limit-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.5);
}
.speed-trend {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.05em;
  color: rgba(244, 240, 230, 0.55);
  text-transform: lowercase;
}
.speed-trend.over { color: #ff8478; }

.levers {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 13px;
}
.lever-label {
  display: block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.48);
  margin-bottom: 5px;
}
.bar {
  height: 7px;
  border-radius: 7px;
  background: rgba(244, 240, 230, 0.12);
  overflow: hidden;
}
.bar i {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 7px;
  background: linear-gradient(90deg, #85cf9a, #2fb370);
  transition: width 0.09s linear;
}
.bar.brake i { background: linear-gradient(90deg, #f4a09a, #e3413b); }

.meters {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 11px;
  padding-top: 9px;
  border-top: 1px solid rgba(244, 240, 230, 0.1);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.45);
}
.meters b {
  color: var(--paper);
  font-family: var(--mono);
  font-weight: 500;
  margin-left: 4px;
}

/* controls ---------------------------------------------------------------- */

.control-panel {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 12px 16px;
  border-radius: 22px;
}

.drive-btn {
  position: relative;
  width: 98px;
  height: 82px;
  border-radius: 16px;
  border: 1px solid rgba(244, 240, 230, 0.2);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.015));
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  transition: transform 0.08s ease, background 0.12s ease, border-color 0.12s ease;
}
.drive-btn:hover { background: linear-gradient(180deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.03)); }
.drive-btn.is-active { transform: translateY(2px) scale(0.985); }
.drive-btn.power.is-active {
  background: linear-gradient(180deg, rgba(53, 185, 122, 0.38), rgba(53, 185, 122, 0.13));
  border-color: rgba(85, 220, 155, 0.6);
}
.drive-btn.brake.is-active {
  background: linear-gradient(180deg, rgba(216, 35, 42, 0.42), rgba(216, 35, 42, 0.15));
  border-color: rgba(255, 110, 100, 0.7);
}
.drive-key {
  display: grid;
  place-items: center;
  width: 23px;
  height: 23px;
  border-radius: 5px;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 600;
  color: rgba(244, 240, 230, 0.72);
  border: 1px solid rgba(244, 240, 230, 0.26);
  background: rgba(0, 0, 0, 0.22);
}
.drive-name {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.drive-btn.power .drive-name { color: #9ce6bd; }
.drive-btn.brake .drive-name { color: #ffada6; }

.mini-controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.round-btn {
  width: 55px;
  height: 31px;
  border-radius: 16px;
  border: 1px solid rgba(244, 240, 230, 0.22);
  background: rgba(244, 240, 230, 0.06);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.8);
  transition: background 0.15s ease, border-color 0.15s ease;
}
.round-btn:hover { background: rgba(244, 240, 230, 0.13); border-color: rgba(244, 240, 230, 0.4); }
.round-btn.is-on {
  background: rgba(53, 185, 122, 0.25);
  border-color: rgba(53, 185, 122, 0.6);
  color: #b6f2d1;
}

/* next stop --------------------------------------------------------------- */

.next-panel {
  padding: 14px 17px 13px;
  min-width: 0;
}
.next-head {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.48);
}
.next-name {
  margin-top: 2px;
  font-family: var(--serif);
  font-size: 29px;
  line-height: 1.05;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.next-meta {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 4px;
  font-family: var(--mono);
  font-size: 11px;
  color: rgba(244, 240, 230, 0.7);
}
.signal-row {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid rgba(244, 240, 230, 0.1);
  font-size: 10px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.62);
}
.signal-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 9px rgba(53, 185, 122, 0.75);
  flex: 0 0 auto;
}
.signal-dot.amber { background: var(--amber); box-shadow: 0 0 9px rgba(239, 174, 61, 0.8); }
.signal-dot.red { background: #ff4a3d; box-shadow: 0 0 10px rgba(255, 74, 61, 0.9); }
.door-state {
  margin-top: 7px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.42);
}
.door-state.open { color: #ffd67c; }

/* ----------------------------------------------------------------- toasts - */

.toasts {
  position: absolute;
  left: 50%;
  bottom: clamp(194px, 26vh, 250px);
  transform: translateX(-50%);
  z-index: 8;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  width: min(92vw, 470px);
  pointer-events: none;
}
.toast {
  max-width: 100%;
  padding: 9px 15px;
  border-radius: 9px;
  border: 1px solid rgba(244, 240, 230, 0.18);
  border-left: 3px solid var(--paper);
  background: rgba(8, 12, 14, 0.88);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(10px);
  font-size: 12px;
  line-height: 1.35;
  letter-spacing: 0.01em;
  text-align: left;
  animation: toast-in 0.28s cubic-bezier(0.2, 0.7, 0.3, 1) both;
}
.toast.ok { border-left-color: var(--green); }
.toast.warn { border-left-color: var(--amber); }
.toast.bad { border-left-color: #ff5b4f; }
.toast.info { border-left-color: #7cb7e8; }
.toast.is-out { animation: toast-out 0.3s ease both; }
@keyframes toast-in {
  from { opacity: 0; transform: translateY(9px) scale(0.98); }
  to { opacity: 1; transform: none; }
}
@keyframes toast-out {
  to { opacity: 0; transform: translateY(-6px); }
}

/* --------------------------------------------------------------- overlays - */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(22px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right))
    max(22px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
  overflow: hidden;
}

.title-screen {
  justify-content: flex-start;
  background:
    radial-gradient(ellipse at 84% 22%, rgba(21, 82, 140, 0.2), transparent 46%),
    linear-gradient(100deg, rgba(7, 10, 12, 0.96) 0%, rgba(7, 10, 12, 0.88) 34%, rgba(7, 10, 12, 0.52) 62%, rgba(7, 10, 12, 0.14) 100%);
  overflow-y: auto;
}
.title-screen::-webkit-scrollbar { width: 8px; }
.title-screen::-webkit-scrollbar-thumb { background: rgba(244, 240, 230, 0.22); border-radius: 8px; }

.screen {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
}

.title-card {
  width: min(740px, 100%);
  margin: auto 0;
  padding: clamp(22px, 4vw, 42px);
  animation: rise 0.7s cubic-bezier(0.18, 0.8, 0.25, 1) both;
}
.title-caption {
  position: absolute;
  right: clamp(20px, 4vw, 46px);
  bottom: clamp(20px, 4vw, 40px);
  display: flex;
  gap: 18px;
  color: rgba(244, 240, 230, 0.5);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
@keyframes rise {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: none; }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #e9c873;
}
.eyebrow .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 10px rgba(216, 35, 42, 0.7);
}

.title-card h1 {
  margin: 13px 0 0;
  font-family: var(--serif);
  font-size: clamp(46px, 6.2vw, 78px);
  font-weight: 400;
  line-height: 0.94;
  letter-spacing: -0.018em;
  text-wrap: balance;
}
.title-card h1 em {
  font-style: italic;
  color: #f1c9a0;
}
.lede {
  max-width: 54ch;
  margin: 18px 0 0;
  font-size: clamp(14px, 1.3vw, 16px);
  line-height: 1.55;
  color: rgba(244, 240, 230, 0.69);
}

.route-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  margin: 22px 0 0;
  padding: 0;
  list-style: none;
  counter-reset: stop;
}
.route-list li {
  counter-increment: stop;
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  padding-right: 19px;
  margin-right: 7px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(244, 240, 230, 0.72);
  white-space: nowrap;
}
.route-list li::before {
  content: counter(stop, decimal-leading-zero);
  font-size: 8px;
  color: rgba(244, 240, 230, 0.36);
}
.route-list li::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  width: 8px;
  height: 1px;
  background: rgba(244, 240, 230, 0.26);
}
.route-list li:last-child { padding-right: 0; margin-right: 0; }
.route-list li:last-child::after { display: none; }

.train-picker {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 24px;
}
.train-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 70px;
  padding: 11px 12px;
  border-radius: 12px;
  border: 1px solid rgba(244, 240, 230, 0.18);
  background: rgba(244, 240, 230, 0.045);
  text-align: left;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}
.train-card:hover { background: rgba(244, 240, 230, 0.09); }
.train-card.is-active {
  border-color: rgba(240, 201, 115, 0.7);
  background: rgba(240, 201, 115, 0.08);
  box-shadow: inset 0 0 0 1px rgba(240, 201, 115, 0.18);
}
.train-card:active { transform: scale(0.99); }
.train-swatch {
  position: relative;
  width: 46px;
  height: 30px;
  border-radius: 4px 8px 3px 3px;
  flex: 0 0 auto;
  background: linear-gradient(180deg, #eeeae2 0 42%, #c8232c 42% 62%, #3a4448 62% 100%);
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.22);
}
.train-swatch::before {
  content: "";
  position: absolute;
  left: 3px;
  right: 3px;
  top: 7px;
  height: 4px;
  background: rgba(28, 38, 44, 0.88);
  box-shadow: 0 8px 0 rgba(28, 38, 44, 0.88);
}
.train-swatch.twindexx {
  background: linear-gradient(180deg, #e9e6de 0 46%, #d8232a 46% 58%, #333d41 58% 100%);
}
.train-copy { min-width: 0; }
.train-copy b {
  display: block;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.train-copy small {
  display: block;
  margin-top: 2px;
  font-size: 10px;
  line-height: 1.25;
  color: rgba(244, 240, 230, 0.5);
}
.train-card .check {
  position: absolute;
  right: 10px;
  top: 9px;
  width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #f0c973;
  color: #1d2224;
  font-size: 10px;
  font-weight: 800;
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 0.16s ease, transform 0.16s ease;
}
.train-card.is-active .check { opacity: 1; transform: none; }

.primary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 26px;
  margin-top: 20px;
  border: 0;
  border-radius: 9px;
  background: var(--red);
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.03em;
  box-shadow: 0 12px 30px rgba(216, 35, 42, 0.32);
  transition: background 0.16s ease, transform 0.16s ease, box-shadow 0.16s ease;
}
.primary-btn svg { width: 18px; height: 18px; fill: currentColor; }
.primary-btn:hover { background: #ea2e35; box-shadow: 0 16px 36px rgba(216, 35, 42, 0.42); }
.primary-btn:active { transform: translateY(1px); }
.hint {
  margin: 13px 0 0;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.045em;
  color: rgba(244, 240, 230, 0.4);
}

/* pause / results -------------------------------------------------------- */

.overlay:has(.pause-screen:not(.is-hidden)),
.overlay:has(.results-screen:not(.is-hidden)) {
  background: rgba(5, 8, 9, 0.62);
  backdrop-filter: blur(7px);
}

.pause-screen, .results-screen { justify-content: center; }

.pause-card, .results-card {
  width: min(520px, 100%);
  padding: clamp(24px, 4vw, 38px);
  border-radius: 18px;
  border: 1px solid rgba(244, 240, 230, 0.16);
  background: linear-gradient(160deg, rgba(20, 27, 30, 0.97), rgba(9, 13, 15, 0.98));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.55);
  animation: rise 0.35s ease both;
}
.pause-card h2, .results-card h2 {
  margin: 10px 0 0;
  font-family: var(--serif);
  font-size: clamp(34px, 4.5vw, 50px);
  font-weight: 400;
  line-height: 1;
}
.pause-card p, .result-sub {
  margin: 12px 0 0;
  font-size: 14px;
  line-height: 1.5;
  color: rgba(244, 240, 230, 0.6);
}
.pause-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 22px;
}
.pause-actions .primary-btn { margin-top: 0; }
.ghost-btn {
  min-height: 52px;
  padding: 0 20px;
  border-radius: 9px;
  border: 1px solid rgba(244, 240, 230, 0.26);
  background: transparent;
  font-size: 13px;
  font-weight: 600;
  transition: background 0.16s ease, border-color 0.16s ease;
}
.ghost-btn:hover { background: rgba(244, 240, 230, 0.08); border-color: rgba(244, 240, 230, 0.45); }

.result-score {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-top: 18px;
}
.result-score span {
  font-family: var(--mono);
  font-size: 54px;
  font-weight: 500;
  letter-spacing: -0.06em;
  color: #f0c973;
}
.result-score small {
  font-family: var(--mono);
  font-size: 13px;
  color: rgba(244, 240, 230, 0.45);
}
.result-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  margin-top: 18px;
  border-radius: 10px;
  overflow: hidden;
  background: rgba(244, 240, 230, 0.1);
}
.result-grid > div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 13px;
  background: rgba(9, 13, 15, 0.95);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: rgba(244, 240, 230, 0.55);
}
.result-grid b {
  font-family: var(--mono);
  font-weight: 500;
  color: var(--paper);
}
.result-line {
  margin-top: 15px;
  font-family: var(--mono);
  font-size: 11px;
  color: rgba(244, 240, 230, 0.62);
}
.result-stops {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 13px;
}
.stop-chip {
  font-family: var(--mono);
  font-size: 9px;
  padding: 4px 7px;
  border-radius: 4px;
  border: 1px solid rgba(244, 240, 230, 0.16);
  color: rgba(244, 240, 230, 0.55);
}
.stop-chip.good { border-color: rgba(53, 185, 122, 0.48); color: #9ce6bd; }
.stop-chip.ok { border-color: rgba(239, 174, 61, 0.48); color: #f5cf8c; }
.stop-chip.bad { border-color: rgba(255, 91, 79, 0.5); color: #ffada6; }

/* ------------------------------------------------------------- responsive - */

@media (max-width: 1080px) {
  .brand-route { display: none; }
  .hud-bottom {
    grid-template-columns: minmax(190px, 250px) auto minmax(190px, 250px);
  }
  .speed-value { font-size: 48px; }
  .drive-btn { width: 84px; height: 74px; }
  .control-panel { gap: 10px; padding: 10px 12px; }
}

@media (max-width: 860px) {
  .hud {
    padding: max(10px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right))
      max(10px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left));
  }
  .topbar { gap: 10px; }
  .clock-block { padding: 7px 12px 8px; }
