  .signal-row { grid-area: signal; margin-top: 4px; padding-top: 5px; border-top: 0; font-size: 9px; }
  .door-state { grid-area: door; margin-top: 4px; text-align: right; font-size: 9px; }
  .speed-panel { grid-area: speed; padding: 11px 13px 10px; border-radius: 14px; }
